    crate::testport::assert_eq(tt_get(tg, 0, 0), 1, "it is the Table element");
    crate::testport::assert_eq(tt_get(tg, 0, 2), 3, "three rows");
    crate::testport::assert_eq(tt_get(tg, 0, 3), 3, "three columns: the second header spans two");
    crate::testport::assert_eq(tt_get(tg, 0, 5), 7, "seven cells");
    crate::testport::assert_eq(tt_get(tg, 0, 13), 1, "one head row: the TH of the THead");
    crate::testport::assert_eq(tt_cget(ta, 1, 4), 2, "the second header's ColSpan");
    crate::testport::assert_eq(tt_cget(ta, 1, 2), 1, "placed in the second column");
