    crate::testport::assert_eq(tt_cget(ta, 3, 2), 1, "the next cell of its row is in the second column");
    crate::testport::assert_eq(tt_cget(ta, 5, 1), 2, "the third row");
    crate::testport::assert_eq(tt_cget(ta, 5, 2), 1, "its first cell skips the column the rowspan holds");
    crate::testport::assert_eq(tt_cget(ta, 6, 2), 2, "and its second is the third column");
    crate::testport::assert_eq(tt_cget(ta, 0, 5), 11, "a TH with Scope Column in a THead: a header (1), for its column (2), in the head (8)");
