#[test]
fn test_the_score_is_a_weighted_harmonic_mean_scaled_by_the_weakest_check() {
    let tg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let acc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    while i < 24 {
        crate::port::cells_push(tg, 0);
        i += 1;
    }
    tt_set(tg, 0, 16, 1000);
    tt_set(tg, 0, 17, 1000);
    tt_set(tg, 0, 18, 1000);
    tt_set(tg, 0, 19, 800);
    tt_set(tg, 0, 20, 1000);
    tt_set(tg, 0, 21, 1000);
    crate::testport::assert_eq(tt_score(tg, 0, acc), 864, "one check at 800 (the cover of a table that misses a row): 960 scaled by 900/1000");
    crate::testport::assert_eq(tt_get(tg, 0, 10), 1, "still confirmed");
    tt_set(tg, 0, 21, 714);
    crate::testport::assert_eq(tt_score(tg, 0, acc), 749, "the geometry agrees on 714 of the words and the cover is 800: partial");
    crate::testport::assert_eq(tt_get(tg, 0, 10), 2, "partial");
    tt_set(tg, 0, 16, 667);
    tt_set(tg, 0, 19, 1000);
    tt_set(tg, 0, 21, 0);
    crate::testport::assert_eq(tt_score(tg, 0, acc), 85, "two visual rows in a TR and a geometry that agrees with none of the words");
    crate::testport::assert_eq(tt_get(tg, 0, 10), 3, "contradicted");
    tt_set(tg, 0, 16, -1);
    tt_set(tg, 0, 17, -1);
    tt_set(tg, 0, 18, -1);
    tt_set(tg, 0, 19, -1);
    tt_set(tg, 0, 20, -1);
    tt_set(tg, 0, 21, -1);
    crate::testport::assert_eq(tt_score(tg, 0, acc), 0, "a table with nothing to check scores nothing");
    crate::testport::assert_eq(tt_get(tg, 0, 10), 3, "and is not believed");
}
