#[test]
fn test_a_tagged_span_is_taken_by_a_table_without_rules_and_flagged_in_a_ruled_one() {
    let tb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ttt_tb(tb, 10000, 10000, 16000, 13000, 1, 900, 2, 2, 0, 4);
    ttt_tc(tc, 0, 0, 1);
    ttt_tc(tc, 0, 1, 1);
    ttt_tc(tc, 1, 0, 1);
    ttt_tc(tc, 1, 1, 1);
    crate::testport::assert_eq(tb_tag_span(tb, 0, tc, 0, 4, 0, 0, 1, 2), 0, "a ruled table keeps its lattice: the first row's two cells stay two");
    crate::testport::assert_eq(crate::port::cells_at(tb, 24), 2, "and the table is flagged: a tagged span crosses an edge the rules close");
    crate::testport::assert_eq(crate::port::cells_at(tc, 3), 1, "the cell is unchanged");
    crate::port::cells_drop(tb, 0);
    crate::port::cells_drop(tc, 0);
    ttt_tb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 4);
    ttt_tc(tc, 0, 0, 1);
    ttt_tc(tc, 0, 1, 0);
    ttt_tc(tc, 1, 0, 1);
    ttt_tc(tc, 1, 1, 1);
    crate::testport::assert_eq(tb_tag_span(tb, 0, tc, 0, 4, 0, 0, 1, 2), 1, "a whitespace table takes the tagged span over an empty cell");
    crate::testport::assert_eq(crate::port::cells_at(tc, 3), 2, "the cell spans two columns");
    crate::testport::assert_eq(crate::port::cells_at(tc, 16 + 12), 1, "the empty cell is absorbed");
    crate::testport::assert_eq(crate::port::cells_at(tc, 6 + 0), 16000, "and the cell's box grows to cover it");
    crate::testport::assert_eq(crate::port::cells_at(tb, 24), 1, "the tags shaped the table");
    crate::port::cells_drop(tb, 0);
    crate::port::cells_drop(tc, 0);
    ttt_tb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 4);
    ttt_tc(tc, 0, 0, 1);
    ttt_tc(tc, 0, 1, 1);
    ttt_tc(tc, 1, 0, 1);
    ttt_tc(tc, 1, 1, 1);
    crate::testport::assert_eq(tb_tag_span(tb, 0, tc, 0, 4, 0, 0, 1, 2), 0, "a span over a cell that has text is not taken");
    crate::testport::assert_eq(crate::port::cells_at(tb, 24), 0, "and nothing is flagged: no rule closes it");
}
#[test]
fn test_ocr_table_hints_break_ties_and_only_ties() {
    let tb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let grg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    ttt_tb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 0);
    ttt_tb(tb, 10100, 10000, 16000, 13000, 3, 720, 2, 2, 0, 0);
    crate::testport::assert_eq(tb_tie_bonus(tb, 0, 0, 2, grg), 0, "no hint, no bonus");
    while i < 16 {
        crate::port::cells_push(grg, 0);
        i += 1;
    }
    crate::port::cells_set(grg, 0, 1);
    crate::port::cells_set(grg, 1, 10000);
    crate::port::cells_set(grg, 2, 10000);
    crate::port::cells_set(grg, 3, 16000);
    crate::port::cells_set(grg, 4, 13000);
    crate::port::cells_set(grg, 5, 3);
    crate::testport::assert_eq(tb_hint_iou(tb, 0, grg), 1000, "the hint is the first candidate's box");
    crate::testport::assert_that(tb_hint_iou(tb, 1, grg) < 1000, "and only nearly the second's");
    crate::testport::assert_eq(tb_tie_bonus(tb, 0, 0, 2, grg), 26, "the first candidate wins the tie: a bonus over the 25 the scores may differ by");
    crate::testport::assert_eq(tb_tie_bonus(tb, 1, 0, 2, grg), 0, "the second does not");
    crate::port::cells_set(tb, TBS + 6, 900);
    crate::testport::assert_eq(tb_tie_bonus(tb, 0, 0, 2, grg), 0, "a candidate 200 better is no tie: OCR does not override the score");
    crate::port::cells_set(grg, 5, 2);
    crate::port::cells_set(tb, TBS + 6, 720);
    crate::testport::assert_eq(tb_tie_bonus(tb, 0, 0, 2, grg), 0, "a region that is not a table hint is not read");
}
